impl Solution{pub fn maximum_gap(a:Vec<i32>)->i32{let n=a.len();if n<2{return 0}let mn=*a.iter().min().unwrap();let mx=*a.iter().max().unwrap();if mn==mx{return 0}let sz=((mx-mn+n as i32-2)/(n as i32-1)).max(1);let bc=((mx-mn)/sz+1)as usize;let mut lo=vec![i32::MAX;bc];let mut hi=vec![i32::MIN;bc];let mut u=vec![false;bc];for x in a{let k=((x-mn)/sz)as usize;u[k]=true;lo[k]=lo[k].min(x);hi[k]=hi[k].max(x);}let(mut p,mut b)=(mn,0);for i in 0..bc{if u[i]{b=b.max(lo[i]-p);p=hi[i];}}b}}
